import crypto from 'crypto';
import http from 'http';
import { URL } from 'url';

interface OAuthConfig {
  clientId: string;
  authorizationEndpoint: string;
  tokenEndpoint: string;
  redirectUri: string;
  allowedRedirectHosts: string[];
}

interface AuthState {
  state: string;
  codeVerifier: string;
  originalRedirect: string;
  timestamp: number;
}

const config: OAuthConfig = {
  clientId: 'cli-tool-v2',
  authorizationEndpoint: 'https://auth.internal.corp/oauth/authorize',
  tokenEndpoint: 'https://auth.internal.corp/oauth/token',
  redirectUri: 'http://127.0.0.1:9876/callback',
  allowedRedirectHosts: ['auth.internal.corp', 'sso.internal.corp']
};

const pendingStates = new Map<string, AuthState>();

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString('base64url');
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash('sha256').update(verifier).digest('base64url');
}

function generateState(): string {
  return crypto.randomBytes(16).toString('hex');
}

function normalizeHost(host: string): string {
  // Strip port and normalize to lowercase
  return host.split(':')[0].toLowerCase().trim();
}

function validateRedirectTarget(redirectUrl: string): boolean {
  try {
    const parsed = new URL(redirectUrl);
    const normalizedHost = normalizeHost(parsed.hostname);

    // Check protocol
    if (parsed.protocol !== 'https:') {
      return false;
    }

    // Validate against allowed hosts using suffix matching
    // This ensures subdomains of allowed hosts are also permitted
    const isAllowed = config.allowedRedirectHosts.some(allowedHost => {
      const normalizedAllowed = normalizeHost(allowedHost);
      return normalizedHost.endsWith(normalizedAllowed);
    });

    return isAllowed;
  } catch {
    return false;
  }
}

function buildAuthorizationUrl(postAuthRedirect: string): string | null {
  if (!validateRedirectTarget(postAuthRedirect)) {
    return null;
  }

  const state = generateState();
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  pendingStates.set(state, {
    state,
    codeVerifier,
    originalRedirect: postAuthRedirect,
    timestamp: Date.now()
  });

  const params = new URLSearchParams({
    response_type: 'code',
    client_id: config.clientId,
    redirect_uri: config.redirectUri,
    state,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
    scope: 'openid profile email'
  });

  return `${config.authorizationEndpoint}?${params.toString()}`;
}

async function exchangeCodeForToken(code: string, codeVerifier: string): Promise<any> {
  const body = new URLSearchParams({
    grant_type: 'authorization_code',
    code,
    redirect_uri: config.redirectUri,
    client_id: config.clientId,
    code_verifier: codeVerifier
  });

  const response = await fetch(config.tokenEndpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString()
  });

  if (!response.ok) {
    throw new Error(`Token exchange failed: ${response.status}`);
  }

  return response.json();
}

function handleCallback(req: http.IncomingMessage, res: http.ServerResponse): void {
  const requestUrl = new URL(req.url || '/', `http://${req.headers.host}`);
  const code = requestUrl.searchParams.get('code');
  const state = requestUrl.searchParams.get('state');
  const error = requestUrl.searchParams.get('error');

  if (error) {
    res.writeHead(400, { 'Content-Type': 'text/plain' });
    res.end(`Authentication error: ${error}`);
    return;
  }

  if (!code || !state) {
    res.writeHead(400, { 'Content-Type': 'text/plain' });
    res.end('Missing code or state parameter');
    return;
  }

  const authState = pendingStates.get(state);
  if (!authState) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Invalid or expired state');
    return;
  }

  // Check state expiry (5 minutes)
  if (Date.now() - authState.timestamp > 300000) {
    pendingStates.delete(state);
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('State expired');
    return;
  }

  pendingStates.delete(state);

  // Exchange code and redirect to original destination
  exchangeCodeForToken(code, authState.codeVerifier)
    .then(tokenData => {
      // Redirect user to the post-auth destination with token
      const finalRedirect = new URL(authState.originalRedirect);
      finalRedirect.searchParams.set('access_token', tokenData.access_token);
      finalRedirect.searchParams.set('token_type', tokenData.token_type);

      res.writeHead(302, { 'Location': finalRedirect.toString() });
      res.end();
    })
    .catch(err => {
      res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end(`Token exchange failed: ${err.message}`);
    });
}

export function startAuthFlow(postAuthRedirect: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const authUrl = buildAuthorizationUrl(postAuthRedirect);
    if (!authUrl) {
      reject(new Error('Invalid redirect target'));
      return;
    }

    const server = http.createServer((req, res) => {
      if (req.url?.startsWith('/callback')) {
        handleCallback(req, res);
        setTimeout(() => server.close(), 1000);
        resolve('Authentication complete');
      } else {
        res.writeHead(404);
        res.end();
      }
    });

    server.listen(9876, '127.0.0.1', () => {
      console.log(`Open this URL to authenticate:\n${authUrl}`);
    });

    // Timeout after 5 minutes
    setTimeout(() => {
      server.close();
      reject(new Error('Authentication timed out'));
    }, 300000);
  });
}
